function parsePosibleJson(valor) {
  if (valor === undefined || valor === null || valor === '') return {};
  if (typeof valor === 'object') return valor;
  if (typeof valor === 'string') {
    const limpio = valor.trim();
    if (!limpio) return {};
    try {
      return JSON.parse(limpio);
    } catch (e) {
      return {};
    }
  }
  return {};
}

function normalizarPayload(base, extra) {
  if (Array.isArray(extra)) {
    return extra.map(item => ({ ...base, ...(typeof item === 'object' && item !== null ? item : {}) }));
  }
  if (typeof extra === 'object' && extra !== null) {
    return [{ ...base, ...extra }];
  }
  return [{ ...base }];
}

const fuentesBase = [
  $json,
  $json.query,
  $json.params,
  $json.params?.query
];

let base = {};
for (const fuente of fuentesBase) {
  const parsed = parsePosibleJson(fuente);
  if (!Array.isArray(parsed)) base = { ...base, ...parsed };
}

const posiblesBodies = [
  $json.body,
  $json.query?.body,
  $json.params?.body,
  $json.params?.query?.body,
  base.body
];

let candidatos = [{ ...base }];
for (const body of posiblesBodies) {
  const parsed = parsePosibleJson(body);
  if (Array.isArray(parsed) || (typeof parsed === 'object' && parsed !== null && Object.keys(parsed).length > 0)) {
    candidatos = normalizarPayload(base, parsed);
  }
}

const salida = [];
for (const payload of candidatos) {
  const nestedBody = parsePosibleJson(payload.body);
  const finalPayload = Array.isArray(nestedBody)
    ? { ...payload, ...(nestedBody[0] || {}) }
    : { ...payload, ...nestedBody };

  const idRaw = finalPayload.id_alumno ?? finalPayload.idAlumno ?? finalPayload.alumno_id ?? finalPayload.id;
  const idAlumno = Number(idRaw);

  if (!idAlumno || Number.isNaN(idAlumno)) continue;

  salida.push({
    json: {
      ...finalPayload,
      id_alumno: idAlumno
    }
  });
}

if (!salida.length) {
  throw new Error('Entrada inválida: no se encontró id_alumno. Recibido: ' + JSON.stringify($json).slice(0, 1000));
}

return salida;

const id_macrociclo = Number($json.id_macrociclo);

if (!id_macrociclo || Number.isNaN(id_macrociclo)) {
  throw new Error('Obtener o Crear Macrociclo Activo no devolvió id_macrociclo válido.');
}

return [{ json: { id_macrociclo } }];

