const total = parseInt($input.first().json.total_mesos || 0, 10);
let fase = 'Familiarización';

if (total === 1) fase = 'Consolidación';
if (total >= 2) fase = 'Realización';

const id_macrociclo = Number($('Unificador de Macrociclo').first().json.id_macrociclo);
if (!id_macrociclo || Number.isNaN(id_macrociclo)) {
  throw new Error('Calculadora de Fase no recibió id_macrociclo válido desde Unificador de Macrociclo.');
}

return [{
  json: {
    id_macrociclo,
    numero_meso: total + 1,
    fase_tipo: fase
  }
}];

const contexto = $("Obtención de Contexto del Alumno").first().json;

let entrada = {};
try {
  entrada = $("Normalizar Entrada Rutina").first().json || {};
} catch (e) {
  entrada = {};
}

const nivel = contexto.nivel_experiencia || 'P1';
const restriccionesRaw = contexto.restricciones || 'Ninguna';
const listaRestricciones = restriccionesRaw !== 'Ninguna'
  ? restriccionesRaw.split(',').filter(Boolean).map(r => `'${String(r).trim().replace(/'/g, "''")}'`).join(',')
  : "'Ninguna'";

const normalizar = (valor, defecto = '') => String(valor || defecto).trim().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '');

function normalizarObjetivo(valor) {
  const v = normalizar(valor, 'recomposicion_corporal');
  if (['grasa', 'perdida_grasa', 'perdida_de_grasa'].includes(v)) return 'perdida_de_grasa';
  if (['musculo', 'musculatura', 'ganancia_masa_muscular', 'masa_muscular'].includes(v)) return 'musculatura';
  if (['rc', 'recomposicion', 'recomposicion_corporal'].includes(v)) return 'recomposicion_corporal';
  return v;
}

return {
  id_alumno: contexto.id_alumno,
  nivel_alumno: nivel,
  filtro_restricciones: listaRestricciones,
  ultima_sesion_id: contexto.ultima_sesion_id,
  frecuencia_semanal: Number(entrada.frecuencia_semanal || contexto.frecuencia_semanal || 3),
  objetivo: normalizarObjetivo(entrada.objetivo || contexto.objetivo),
  enfoque_principal: normalizar(entrada.enfoque_principal || entrada.enfoque || entrada.tipo_rutina || contexto.enfoque_principal, ''),
  enfoque_especifico: normalizar(entrada.enfoque_especifico || contexto.enfoque_especifico, ''),
  debilidad: normalizar(entrada.debilidad || contexto.debilidad, ''),
  prioridad_recomposicion: normalizar(entrada.prioridad_recomposicion || contexto.prioridad_recomposicion, 'musculatura')
};

const filtros = $("Preparador de Filtros").first().json;
const frecuencia = Math.max(1, Math.min(5, Number(filtros.frecuencia_semanal || 3)));
const objetivo = filtros.objetivo || 'recomposicion_corporal';
const prioridadRecomp = filtros.prioridad_recomposicion || 'musculatura';
const debilidad = filtros.debilidad || '';
const enfoqueEspecifico = filtros.enfoque_especifico || '';
const esPerdidaGrasa = objetivo === 'perdida_de_grasa' || (objetivo === 'recomposicion_corporal' && prioridadRecomp === 'perdida_de_grasa');

const NORMAL = {
  full_body: ['full_body', 'fullbody', 'cuerpo_completo', 'ff'],
  torso: ['torso', 'aem', 'agarre_empuje_mixto'],
  pierna: ['pierna', 'piernas'],
  pierna_torso: ['pierna_torso', 'pt'],
  torso_pierna: ['torso_pierna', 'tp'],
  fullbody_torso_pierna: ['fullbody_torso_pierna', 'full_body_torso_pierna', 'full_body_pierna_torso', 'fullbody_pierna_torso', 'fpt'],
  torso_pierna_torso: ['torso_pierna_torso', 'tpt'],
  pierna_torso_pierna: ['pierna_torso_pierna', 'ptp'],
  pierna_torso_pierna_torso: ['pierna_torso_pierna_torso', 'ptpt'],
  torso_torso_pierna_torso: ['torso_torso_pierna_torso', 'ttpt', 'aepm', 'agarre_empuje_pierna_mixto']
};

function resolverRutina() {
  const solicitado = filtros.enfoque_principal || '';
  for (const [tipo, alias] of Object.entries(NORMAL)) {
    if (!alias.includes(solicitado)) continue;
    if (tipo === 'full_body' && frecuencia >= 3) return 'fullbody_torso_pierna';
    return tipo;
  }
  if (frecuencia <= 2) return 'full_body';
  if (frecuencia === 3) return 'fullbody_torso_pierna';
  return 'pierna_torso_pierna_torso';
}

function musculosPorEnfoque(valor) {
  const v = String(valor || '').toUpperCase();
  const out = [];
  if (v.includes('GLUT')) out.push('GLUTEO');
  if (v.includes('ABDOM')) out.push('ABDOMEN');
  if (v.includes('MANGUIT') || v.includes('ROTADOR')) out.push('MANGUITO');
  if (v.includes('ESPALD')) out.push('ESPALDA');
  if (v.includes('HOMB')) out.push('HOMBRO');
  if (v.includes('PECT') || v.includes('PECHO')) out.push('PECTORAL');
  if (v.includes('BRAZ')) out.push('BICEPS', 'TRICEPS');
  if (v.includes('BICEP')) out.push('BICEPS');
  if (v.includes('TRICEP')) out.push('TRICEPS');
  if (v.includes('CUAD')) out.push('CUADRICEPS');
  if (v.includes('ISQUI')) out.push('ISQUIO');
  if (v.includes('GASTRO') || v.includes('PANTORR')) out.push('GASTROGNEMIO');
  return [...new Set(out)];
}

function normalizarMusculo(valor) {
  if (!valor) return [];
  return String(valor).split('/').flatMap(musculosPorEnfoque);
}

function slot(orden, patron, maquina, tipo, musculo = null, extra = {}) {
  const tipoNormal = String(tipo || '').toUpperCase().replace('TERCEARIO', 'TERCIARIO').replace('TRECERIO', 'TERCIARIO');
  return {
    orden,
    patron_slot: patron || null,
    patrones: patron ? [patron] : [],
    maquina_slot: maquina || null,
    tipo_slot: tipoNormal ? tipoNormal.toLowerCase() : 'complementario',
    tipo_slot_original: tipo || null,
    musculo_slot: musculo || null,
    musculos: normalizarMusculo(musculo),
    ...extra
  };
}

function resolverCoreSlot(zona) {
  const musculos = musculosPorEnfoque(debilidad);
  if (musculos.includes('MANGUITO')) {
    return { valor: 'manguito_rotador', musculos: ['MANGUITO'], motivo: null };
  }
  if (musculos.includes('GLUTEO')) {
    if (zona === 'full_body' || zona === 'pierna') {
      return { valor: 'gluteo', musculos: ['GLUTEO'], motivo: null };
    }
    return { valor: 'abdomen', musculos: ['ABDOMEN'], motivo: 'Debilidad gluteo transformada a abdomen en torso/AEM segun V2.' };
  }
  if (musculos.includes('ABDOMEN')) {
    return { valor: 'abdomen', musculos: ['ABDOMEN'], motivo: null };
  }
  return { valor: 'abdomen', musculos: ['ABDOMEN'], motivo: 'Sin debilidad informada; V2 usa abdomen como slot 1 por defecto.' };
}

function debilidadSlot(zona) {
  const core = resolverCoreSlot(zona);
  return {
    orden: 1,
    patron_slot: null,
    patrones: [],
    maquina_slot: null,
    tipo_slot: 'debilidad',
    tipo_slot_original: core.valor === 'abdomen' && !debilidad ? 'CORE_DEFAULT' : 'DEBILIDAD',
    zona,
    musculo_slot: core.valor,
    objetivo_muscular: core.valor,
    musculos: core.musculos,
    fallback_plan: core.motivo
  };
}

function complementarioSlot(orden, zona) {
  return slot(
    orden,
    esPerdidaGrasa ? 'AEROBICO' : null,
    null,
    esPerdidaGrasa ? 'AEROBICO' : 'TERCIARIO',
    enfoqueEspecifico || null,
    {
      zona,
      objetivo_muscular: enfoqueEspecifico || null,
      musculos: enfoqueEspecifico ? musculosPorEnfoque(enfoqueEspecifico) : []
    }
  );
}

function dia(diaNumero, diaTipo, focoDia, slotsBase, opciones = {}) {
  const base = [];
  const deb = debilidadSlot(diaTipo);
  const tieneDebilidad = !!deb;
  const fallbackDebilidadDia = deb?.fallback_plan || null;
  const agregarComplementario = (orden) => {
    if (!base.some(s => Number(s.orden) === Number(orden))) {
      base.push(complementarioSlot(orden, diaTipo));
    }
  };

  if (deb) base.push(deb);
  for (const s of slotsBase) base.push({ ...s, zona: diaTipo });

  if (opciones.complementario !== false) {
    agregarComplementario(opciones.ordenComplementario || 6);
  }
  if (!tieneDebilidad) {
    agregarComplementario(7);
  }

  return base.map(s => ({
    ...s,
    dia_numero: diaNumero,
    dia_tipo: diaTipo,
    foco_dia: focoDia,
    fuente_matriz: opciones.fuente_matriz || diaTipo,
    objetivo_muscular: s.objetivo_muscular || (s.musculos?.length ? enfoqueEspecifico || s.musculo_slot : null),
    fallback_plan: fallbackDebilidadDia
  }));
}

