function contextoDia(diaSlots) {
  const ref = diaSlots[0] || {};
  return {
    dia_numero: ref.dia_numero,
    dia_tipo: ref.dia_tipo,
    foco_dia: ref.foco_dia,
    fuente_matriz: ref.fuente_matriz
  };
}

function ordenarDia(diaSlots) {
  return [...diaSlots].sort((a, b) => Number(a.orden) - Number(b.orden));
}

function crearSlotDia(diaSlots, orden, patron, maquina, tipo, musculo = null, fuente = 'AJUSTE_ENFOQUE') {
  const ctx = contextoDia(diaSlots);
  const creado = slot(orden, patron, maquina, tipo, musculo, {
    zona: ctx.dia_tipo,
    objetivo_muscular: musculo || null
  });
  return {
    ...creado,
    ...ctx,
    zona: ctx.dia_tipo,
    fuente_matriz: `${ctx.fuente_matriz || ctx.dia_tipo}_${fuente}`
  };
}

function setSlotDia(diaSlots, orden, patron, maquina, tipo, musculo = null, fuente = 'AJUSTE_ENFOQUE') {
  const limpio = diaSlots.filter(s => Number(s.orden) !== Number(orden));
  limpio.push(crearSlotDia(diaSlots, orden, patron, maquina, tipo, musculo, fuente));
  return ordenarDia(limpio);
}

function quitarSlotDia(diaSlots, orden) {
  return ordenarDia(diaSlots.filter(s => Number(s.orden) !== Number(orden)));
}

function aplicarSpecs(diaSlots, specs, fuente = 'AJUSTE_ENFOQUE') {
  let out = diaSlots;
  for (const spec of specs) {
    out = setSlotDia(out, spec[0], spec[1], spec[2], spec[3], spec[4] || null, fuente);
  }
  return out;
}

function enfoqueIncluye(...tokens) {
  const v = String(enfoqueEspecifico || '').toUpperCase();
  return tokens.some(t => v.includes(t));
}

const enfoqueHombro = enfoqueIncluye('HOMB');
const enfoquePecho = enfoqueIncluye('PECHO', 'PECT');
const enfoqueEspalda = enfoqueIncluye('ESPALD');
const enfoqueBrazos = enfoqueIncluye('BRAZ', 'BICEP', 'TRICEP');
const sinDebilidad = !debilidad;
const esMusculatura = objetivo === 'musculatura';

function aplicarPerdidaGrasa(diaSlots) {
  let out = diaSlots;
  const ctx = contextoDia(out);
  if (!esPerdidaGrasa || ctx.dia_tipo === 'cardio') return out;

  out = quitarSlotDia(out, 7);

  if (ctx.dia_tipo === 'pierna') {
    const tieneSlotDebilidad = out.some(s => Number(s.orden) === 1 && String(s.tipo_slot || '').toLowerCase() === 'debilidad');
    const ordenAerobico = 6;
    out = setSlotDia(out, ordenAerobico, 'AEROBICO', null, 'AEROBICO', null, 'PERDIDA_GRASA_PIERNA_SLOT_6_V2');
    return ordenarDia(out);
  }

  out = setSlotDia(out, 6, 'AEROBICO', null, 'AEROBICO', null, 'PERDIDA_GRASA');

  if (ctx.dia_tipo === 'torso') {
    const esDiaBrazos = (rutinaTipo === 'torso' && frecuencia === 3 && Number(ctx.dia_numero) === 3)
      || (rutinaTipo === 'torso_torso_pierna_torso' && Number(ctx.dia_numero) === 4);

    if (esDiaBrazos) {
      out = aplicarSpecs(out, [
        [2, 'TRACCION', null, 'PRIMARIO', 'BICEPS'],
        [3, 'EMPUJE', null, 'PRIMARIO', 'TRICEPS'],
        [4, 'TRACCION', null, 'SECUNDARIO', 'BICEPS'],
        [5, 'EMPUJE', null, 'TERCIARIO', 'TRICEPS']
      ], 'PERDIDA_GRASA_TORSO_BRAZOS');
    } else if (ctx.foco_dia === 'empuje' || Number(ctx.dia_numero) === 2 || Number(ctx.dia_numero) === 4) {
      out = aplicarSpecs(out, [
        [2, 'EMPUJE', 'NO', 'PRIMARIO', 'PECHO'],
        [3, 'TRACCION', 'NO', 'PRIMARIO', null],
        [4, 'EMPUJE', 'SI', 'SECUNDARIO', 'HOMBRO'],
        [5, 'TRACCION', 'SI', 'SECUNDARIO', null]
      ], 'PERDIDA_GRASA_TORSO_EMPUJE');
    } else {
      out = aplicarSpecs(out, [
        [2, 'TRACCION', 'NO', 'PRIMARIO', null],
        [3, 'EMPUJE', 'NO', 'PRIMARIO', null],
        [4, 'TRACCION', 'SI', 'SECUNDARIO', null],
        [5, 'EMPUJE', 'SI', 'SECUNDARIO', null]
      ], 'PERDIDA_GRASA_TORSO_MIXTO');
    }
  }

  return ordenarDia(out);
}

