        [4, 'EMPUJE', null, 'SECUNDARIO', 'PECHO'],
        [5, 'TRACCION', null, 'SECUNDARIO', null]
      ], 'ENFOQUE_HOMBRO');
      if (sinDebilidad && (esMusculatura || esPerdidaGrasa)) out = setSlotDia(out, 1, 'EMPUJE', null, 'TERCIARIO', 'HOMBRO', 'ENFOQUE_HOMBRO');
      if (esPerdidaGrasa) out = setSlotDia(out, 6, 'AEROBICO', null, 'AEROBICO', null, 'ENFOQUE_HOMBRO');
