      ], 'ENFOQUE_PECHO');
      if (sinDebilidad && (esMusculatura || esPerdidaGrasa)) out = setSlotDia(out, 1, 'EMPUJE', null, 'TERCIARIO', 'PECHO', 'ENFOQUE_PECHO');
      if (esPerdidaGrasa) out = setSlotDia(out, 6, 'AEROBICO', null, 'AEROBICO', null, 'ENFOQUE_PECHO');
      else out = setSlotDia(out, 6, 'EMPUJE', null, 'TERCIARIO', 'PECHO', 'ENFOQUE_PECHO');
      out = quitarSlotDia(out, 7);
    }
  }

  if (enfoqueEspalda) {
    if (ctx.dia_tipo === 'full_body' && sinDebilidad && esPerdidaGrasa) {
      out = setSlotDia(out, 1, 'TRACCION', null, 'TERCIARIO', 'ESPALDA', 'ENFOQUE_ESPALDA');
      out = quitarSlotDia(out, 7);
    }
    if (ctx.dia_tipo === 'torso') {
      out = aplicarSpecs(out, [
        [2, 'TRACCION', null, 'PRIMARIO', 'ESPALDA'],
        [3, 'EMPUJE', null, 'PRIMARIO', 'PECHO'],
        [4, 'TRACCION', null, 'SECUNDARIO', 'ESPALDA'],
        [5, 'EMPUJE', null, 'SECUNDARIO', 'PECHO']
      ], 'ENFOQUE_ESPALDA');
      if (sinDebilidad && esPerdidaGrasa) out = setSlotDia(out, 1, 'TRACCION', null, 'TERCIARIO', 'ESPALDA', 'ENFOQUE_ESPALDA');
      if (esPerdidaGrasa) out = setSlotDia(out, 6, 'AEROBICO', null, 'AEROBICO', null, 'ENFOQUE_ESPALDA');
      else out = setSlotDia(out, 6, 'TRACCION', null, 'TERCIARIO', 'ESPALDA', 'ENFOQUE_ESPALDA');
      out = quitarSlotDia(out, 7);
    }
  }

  if (enfoqueBrazos) {
    if (ctx.dia_tipo === 'full_body' && Number(ctx.dia_numero) === 1) {
      if (esPerdidaGrasa) {
        out = aplicarSpecs(out, [
          [2, 'SENTADILLA', 'NO', 'PRIMARIO', null],
          [3, 'CADERA', 'NO', 'PRIMARIO', null],
          [4, 'TRACCION', null, 'TERCIARIO', 'BICEPS'],
          [5, 'EMPUJE', null, 'TERCIARIO', 'TRICEPS'],
          [6, 'AEROBICO', null, 'AEROBICO', null]
        ], 'ENFOQUE_BRAZOS');
        out = quitarSlotDia(out, 7);
      } else if (esMusculatura) {
        out = aplicarSpecs(out, [
          [2, 'SENTADILLA', 'NO', 'PRIMARIO', null],
          [3, 'CADERA', 'NO', 'PRIMARIO', null],
          [4, 'TRACCION', null, 'SECUNDARIO', 'ESPALDA'],
          [5, 'TRACCION', null, 'TERCIARIO', 'BICEPS'],
          [6, 'EMPUJE', null, 'TERCIARIO', 'TRICEPS']
        ], 'ENFOQUE_BRAZOS');
        out = quitarSlotDia(out, 7);
      }
    }
    if (ctx.dia_tipo === 'torso') {
      if (esPerdidaGrasa) {
        out = aplicarSpecs(out, [
          [4, 'TRACCION', null, 'TERCIARIO', 'BICEPS'],
          [5, 'EMPUJE', null, 'TERCIARIO', 'TRICEPS'],
          [6, 'AEROBICO', null, 'AEROBICO', null]
        ], 'ENFOQUE_BRAZOS');
        out = quitarSlotDia(out, 7);
      } else if (esMusculatura) {
        out = aplicarSpecs(out, [
          [5, 'TRACCION', null, 'TERCIARIO', 'BICEPS'],
          [6, 'EMPUJE', null, 'TERCIARIO', 'TRICEPS']
        ], 'ENFOQUE_BRAZOS');
        out = quitarSlotDia(out, 7);
      }
    }
  }

  return ordenarDia(out);
}

function normalizarReglasFinalesDia(diaSlots) {
  let out = ordenarDia(diaSlots);
  const ctx = contextoDia(out);
  const esTipo = tipo => String(tipo || '').toLowerCase();
  const esAerobicoSlot = s => esTipo(s.tipo_slot) === 'aerobico' || String(s.patron_slot || '').toUpperCase() === 'AEROBICO';
  const maxDia = ctx.dia_tipo === 'cardio' ? 1 : 6;
  const objetivoDia = ctx.dia_tipo === 'cardio' ? 1 : 6;

  if (ctx.dia_tipo === 'torso') {
    out = out.filter(s => {
      const patron = String(s.patron_slot || '').toUpperCase();
      const musculos = (s.musculos || []).map(m => String(m).toUpperCase());
      const esDebilidadGluteo = esTipo(s.tipo_slot) === 'debilidad' && musculos.includes('GLUTEO');
      return !['SENTADILLA', 'CADERA'].includes(patron) && !esDebilidadGluteo;
    });
  }

  if (ctx.dia_tipo === 'pierna') {
    out = out.filter(s => {
      const musculos = (s.musculos || []).map(m => String(m).toUpperCase());
      if (esTipo(s.tipo_slot) === 'debilidad') return true;
      const musculoTorso = musculos.some(m => ['ESPALDA', 'PECTORAL', 'PECHO', 'HOMBRO', 'BICEPS', 'TRICEPS', 'MANGUITO'].includes(m));
      return !musculoTorso || esAerobicoSlot(s);
    });
  }

  let aerobico = out.find(esAerobicoSlot) || null;
  out = out.filter(s => !esAerobicoSlot(s));

  if (esPerdidaGrasa && ctx.dia_tipo !== 'cardio' && !aerobico) {
    aerobico = crearSlotDia(out.length ? out : diaSlots, maxDia, 'AEROBICO', null, 'AEROBICO', null, 'NORMALIZACION_AEROBICO');
  }

  const patronesTorso = ['TRACCION', 'EMPUJE', 'TRACCION', 'EMPUJE'];
  const musculosTorso = enfoqueEspalda
    ? ['ESPALDA', 'PECHO', 'ESPALDA', 'PECHO']
    : enfoqueHombro
      ? ['HOMBRO', null, 'PECHO', null]
      : enfoquePecho
        ? ['PECHO', null, 'PECHO', null]
        : [null, null, null, null];
  const patronesPierna = ['CADERA', 'SENTADILLA', 'CADERA', 'SENTADILLA'];
  const patronesFullBody = ['SENTADILLA', 'AGARRE', 'CADERA', 'EMPUJE'];

  function rellenarHastaObjetivo() {
    let guard = 0;
    while (out.length + (aerobico ? 1 : 0) < objetivoDia && guard < 10) {
      guard++;
      const posicion = out.length;
      let patron = null;
      let maquina = null;
      let tipo = posicion < 2 ? 'PRIMARIO' : 'SECUNDARIO';
      let musculo = null;
      if (ctx.dia_tipo === 'torso') {
        patron = patronesTorso[posicion % patronesTorso.length];
        musculo = musculosTorso[posicion % musculosTorso.length];
      } else if (ctx.dia_tipo === 'pierna') {
        patron = patronesPierna[posicion % patronesPierna.length];
      } else if (ctx.dia_tipo === 'full_body') {
        patron = patronesFullBody[posicion % patronesFullBody.length];
      } else if (ctx.dia_tipo === 'cardio') {
        patron = 'AEROBICO';
        tipo = 'AEROBICO';
      }
      out.push(crearSlotDia(out.length ? out : diaSlots, out.length + 1, patron, maquina, tipo, musculo, 'NORMALIZACION_CONTEO'));
    }
  }

  rellenarHastaObjetivo();

  if (aerobico) {
    const fuerzaMax = Math.max(0, maxDia - 1);
    out = out.slice(0, fuerzaMax);
    out.push({
      ...aerobico,
      orden: maxDia,
      fallback_plan: [aerobico.fallback_plan, ctx.dia_tipo === 'pierna' ? 'V2: aerobico ocupa slot 6 en pierna para perdida de grasa/recomposicion.' : null].filter(Boolean).join(' | ')
    });
  } else {
    out = out.slice(0, maxDia);
  }

  return ordenarDia(out).map((s, idx) => ({
    ...s,
    orden: idx + 1,
    orden_original_ajustada: s.orden_original_ajustada || s.orden
  }));
}

dias = dias.map(d => normalizarReglasFinalesDia(aplicarEnfoqueEspecifico(aplicarPerdidaGrasa(d))));

const slots = dias.flat();
const patrones = [...new Set(slots.flatMap(s => s.patrones || []))];
const patronesConsulta = [...new Set([...patrones, ...(patrones.includes('AGARRE') ? ['TRACCION'] : [])])];
const musculos = [...new Set(slots.flatMap(s => s.musculos || []))];
const sqlList = arr => arr.length ? arr.map(p => `'${String(p).replace(/'/g, "''")}'`).join(',') : "''";

