const contiene = (valor, buscado) => limpiar(valor).includes(limpiar(buscado));
function canonTipo(tipo) {
  const t = limpiar(tipo).replace('SECUNDARIO_RECOMENDADO', 'SECUNDARIO').replace('TERCEARIO', 'TERCIARIO').replace('TRECERIO', 'TERCIARIO');
  return t;
}
function esMaquina(ej) { return limpiar(ej.maquina) === 'SI' || limpiar(ej.maquina) === 'TRUE'; }
function coincidePatron(ej, slot) {
  const patron = limpiar(ej.patron_movimiento);
  const solicitado = limpiar(slot.patron_slot || slot.patrones?.[0]);
  if (!solicitado) return true;
  if (patron === solicitado || contiene(ej.nombre, solicitado)) return true;
  if (solicitado === 'AGARRE' && patron === 'TRACCION') return true;
  return false;
}
function fallbackPatron(ej, slot) {
  return limpiar(slot.patron_slot) === 'AGARRE' && limpiar(ej.patron_movimiento) === 'TRACCION';
}
function coincideMusculo(ej, musculos = []) {
