}
function coincideTipo(ej, slot) {
  const tipo = canonTipo(slot.tipo_slot_original || slot.tipo_slot);
  if (tipo === 'PRIMARIO') return !!ej.es_primario;
  if (tipo === 'SECUNDARIO') return !!ej.es_secundario;
  if (tipo === 'TERCIARIO') return !!ej.es_terciario;
  if (tipo === 'AEROBICO') return limpiar(ej.patron_movimiento) === 'AEROBICO';
  if (tipo === 'DEBILIDAD') return true;
  return true;
}
function coincideMaquina(ej, slot) {
