}

const MUSCULOS_PIERNA = new Set(['CUADRICEPS', 'ISQUIO', 'ISQUIOTIBIAL', 'GLUTEO', 'ADUCTOR', 'GASTROCNEMIO', 'GASTROGNEMIO', 'PANTORRILLA']);
