  if (regla.maquina === 'SI' && !esMaquina(ej)) return false;
  if ((regla.maquina === 'NO' || regla.maquina === 'LIBRE') && esMaquina(ej)) return false;
  if (regla.mono && !esMonoarticular(ej)) return false;
