  if (usadosMicrociclo.has(ej.id_ejercicio)) score -= 1000;
  if (!compatibleZona(ej, slot)) score -= 1000; else score += 18;
  score += scoreMesociclo(ej, slot);
  if (coincidePatron(ej, slot)) score += fallbackPatron(ej, slot) ? 25 : 55;
  if (coincideMaquina(ej, slot)) score += 24; else score -= 18;
  if (coincideTipo(ej, slot)) score += 32; else score -= 10;
  if (coincideMusculo(ej, slot.musculos)) score += 30;
  if (slot.tipo_slot === 'debilidad') score += 20;
  if (ej.es_axial && nivelMetodo === 'P1') score -= 25;
  if (limpiar(ej.dificultad) === 'BAJA') score += 8;
  if (limpiar(ej.dificultad) === 'MEDIA') score += 4;
