}
function elegirEjercicio(slot, usadosDia, usadosMicrociclo) {
  return [...candidatos]
    .map(ej => ({ ej, score: scoreEjercicio(ej, slot, usadosDia, usadosMicrociclo) }))
    .filter(x => x.score > -500 && coincidePatron(x.ej, slot) && compatibleZona(x.ej, slot) && cumpleReglaMesociclo(x.ej, slot))
    .sort((a, b) => b.score - a.score || a.ej.id_ejercicio - b.ej.id_ejercicio)[0];
}

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, n));
}
function round2(n) {
  return Number(n || 0).toFixed(2);
}
function parseHistDos(hist) {
  if (!hist) return [];
  if (Array.isArray(hist)) return hist;
  if (typeof hist === 'string') {
    try { return JSON.parse(hist); } catch (e) { return []; }
  }
  return [];
}
function descansoPorRir(rirMin, rirMax, esMulti, esAerobico) {
  if (esAerobico) return 0;
  const rir = Math.round(((Number(rirMin) || 0) + (Number(rirMax) || 0)) / 2);
  if (rir >= 3) return esMulti ? 90 : 60;
  if (rir === 2) return esMulti ? 120 : 90;
  if (rir === 1) return esMulti ? 150 : 90;
  return esMulti ? 180 : 120;
}
function rangoInicial(nivel, esMono) {
  if (nivel === 'P2') return esMono ? [10, 12] : [8, 10];
  if (nivel === 'P1') return esMono ? [12, 15] : [10, 12];
  return esMono ? [10, 12] : [8, 12];
}
function umbralBajo(nivel, esMono, repsMin, repsMax) {
  if (nivel === 'P2' && !esMono && repsMin === 8 && repsMax === 10) return 9;
  return 11;
}
function pctDescarga(nivel, esMono) {
  if (nivel === 'P2' && !esMono) return 0.95;
  if (['I1', 'I2'].includes(nivel)) return 0.975;
  return 0.90;
}
function pctSubida(nivel) {
  if (nivel === 'I2') return 1.025;
  return 1.05;
}
function evaluarFallos(hist, repsMin, repsMax, nivel, esMono) {
  const datos = parseHistDos(hist).slice(0, 2);
  if (datos.length < 2) return false;
  const threshold = (repsMin <= 8 && repsMax <= 10 && nivel === 'P2' && !esMono) ? 9 : (repsMax >= 15 ? 13.5 : 11);
  return datos.every(x => Number(x.reps_promedio) <= threshold);
}
function progresionBase(ejercicio, slot, ref, semana, rirMin, rirMax) {
  const tipo = canonTipo(slot.tipo_slot_original || slot.tipo_slot);
  const esAerobico = tipo === 'AEROBICO';
  const esIso = limpiar(ejercicio.patron_movimiento).includes('ISOMETR') || limpiar(ejercicio.nombre).includes('ISOMETR');
  const esBanda = limpiar(ejercicio.equipo_necesario).includes('BANDA') || limpiar(ejercicio.accesorio).includes('BANDA');
  const esMono = esMonoarticular(ejercicio) || tipo === 'TERCIARIO' || tipo === 'DEBILIDAD';
  const esMulti = !esMono;

  if (esAerobico) {
    return {
      series: 0,
      reps_min: 0,
      reps_max: 0,
      peso: 0,
      tempo: 'CONTINUO',
      descanso: 0,
      duracion: 10,
      estado: 'aerobico_10_min',
      comentario: nivelMetodo === 'P1' ? 'Aerobico suave 10 minutos' : 'Aerobico media intensidad 10 minutos'
    };
  }

  if (esIso) {
    const baseSeg = Number(ref?.duracion_objetivo_min_origen || 0) > 0 ? Number(ref.duracion_objetivo_min_origen) * 60 : 20;
    const realizado = Number(ref?.duracion_realizada_min || 0) * 60;
    const cumple = realizado >= baseSeg;
    const siguienteSeg = cumple ? clamp(baseSeg + 5, 15, 60) : clamp(baseSeg - 5, 15, 60);
    const series = cumple ? clamp(Number(ref?.series_origen || 3), 3, 4) : clamp(Number(ref?.series_origen || 3) + 1, 3, 4);
    return {
      series,
      reps_min: siguienteSeg,
      reps_max: siguienteSeg,
      peso: Number(ref?.peso_referencia || 0),
      tempo: 'ISOMETRICO',
      descanso: descansoPorRir(rirMin, rirMax, esMulti, false),
      duracion: Math.round(siguienteSeg / 60),
      estado: cumple ? 'isometrico_sube_5s' : 'isometrico_baja_5s_o_sube_series',
      comentario: 'Escala isometrica provisional: 15-20-25-30-35-40-45-50-55-60 segundos; pendiente validacion metodologica'
    };
  }

  const inicial = rangoInicial(nivelMetodo, esMono);
  let repsMin = Number(ref?.reps_min_origen || inicial[0]);
  let repsMax = Number(ref?.reps_max_origen || inicial[1]);
  let series = clamp(Number(ref?.series_origen || ref?.series_ultima || 3), 3, 4);
  let peso = Number(ref?.peso_referencia || 0);
  const promedio = Number(ref?.reps_promedio_ultima || 0);
  const dosFallos = evaluarFallos(ref?.ultimas_dos_semanas, repsMin, repsMax, nivelMetodo, esMono);
  let estado = 'sin_historial_mantener_rango';
  let comentario = 'Microciclo pendiente de ejecucion; se recalcula con los ultimos logs por isosemana lunes-domingo';

  if (promedio > 0) {
    const esP2MultiBajo = nivelMetodo === 'P2' && !esMono && repsMin === 8 && repsMax === 10;
    const esRangoBajo = (esP2MultiBajo || (repsMin === 10 && repsMax === 12));
    const esRangoAlto = repsMin === 12 && repsMax === 15 || (nivelMetodo === 'P2' && !esMono && repsMin === 10 && repsMax === 12);

    if (esRangoBajo) {
      const threshold = umbralBajo(nivelMetodo, esMono, repsMin, repsMax);
      if (promedio >= threshold) {
        if (nivelMetodo === 'P2' && !esMono) [repsMin, repsMax] = [10, 12]; else [repsMin, repsMax] = [12, 15];
        estado = 'sube_rango_repeticiones';
      } else if (dosFallos) {
        peso = peso > 0 ? peso * pctDescarga(nivelMetodo, esMono) : 0;
        estado = 'descarga_por_dos_fallos';
      } else {
        estado = 'mantener_por_primer_fallo';
      }
    } else if (esRangoAlto) {
      const threshold = (repsMax === 15) ? 13.5 : 11;
      if (promedio > threshold) {
        if (series < 4) {
          series += 1;
          estado = 'sube_serie';
        } else {
          peso = peso > 0 ? peso * pctSubida(nivelMetodo) : 0;
          [repsMin, repsMax] = (nivelMetodo === 'P2' && !esMono) ? [8, 10] : [10, 12];
          estado = 'sube_carga_y_reinicia_rango';
        }
      } else if (dosFallos) {
        if (series < 4) {
          series += 1;
          [repsMin, repsMax] = (nivelMetodo === 'P2' && !esMono) ? [8, 10] : [10, 12];
          estado = 'sube_serie_y_reinicia_rango_por_dos_fallos';
        } else {
          peso = peso > 0 ? peso * pctDescarga(nivelMetodo, esMono) : 0;
          [repsMin, repsMax] = (nivelMetodo === 'P2' && !esMono) ? [8, 10] : [10, 12];
          estado = 'descarga_y_reinicia_rango_por_dos_fallos';
        }
      } else {
        estado = 'mantener_rango_alto_por_primer_fallo';
      }
    }
    comentario = `Ultima isosemana: promedio reps ${promedio.toFixed(1)}; estado ${estado}`;
  }

  if (esBanda) {
    comentario += ' | Bandas: progresion por color pendiente de tabla oficial; por ahora mantener color y subir al superar rango objetivo dos semanas seguidas';
  }

  return {
    series,
    reps_min: repsMin,
    reps_max: repsMax,
    peso,
    tempo: '1-1-2',
    descanso: descansoPorRir(rirMin, rirMax, esMulti, false),
    duracion: null,
    estado,
    comentario
  };
}

const salida = [];
const seleccionBase = [];
const usadosMicrociclo = new Set();

for (const dia of plan.dias_planificados) {
  const usadosDia = new Set();
  let ordenSalidaDia = 1;
  const slotsDia = [...dia].sort((a, b) => Number(a.orden || 0) - Number(b.orden || 0));

  for (const slot of slotsDia) {
    const elegido = elegirEjercicio(slot, usadosDia, usadosMicrociclo);
    if (!elegido) continue;

    const ejercicio = elegido.ej;
    usadosDia.add(ejercicio.id_ejercicio);
    usadosMicrociclo.add(ejercicio.id_ejercicio);

    const fallback = fallbackPatron(ejercicio, slot) || !coincideMaquina(ejercicio, slot) || !coincideTipo(ejercicio, slot);
    const motivosFallback = [
      fallbackPatron(ejercicio, slot) ? 'AGARRE resuelto con TRACCION' : null,
      !coincideMaquina(ejercicio, slot) ? `maquina requerida ${slot.maquina_slot || 'sin restriccion'} no exacta` : null,
      !coincideTipo(ejercicio, slot) ? `tipo requerido ${slot.tipo_slot_original || slot.tipo_slot} no exacto` : null,
      !compatibleZona(ejercicio, slot) ? 'zona/tren no compatible' : null,
      slot.fallback_plan ? slot.fallback_plan : null
    ].filter(Boolean).join('; ');

    seleccionBase.push({
      slot,
      ejercicio,
      orden_ejercicio: ordenSalidaDia++,
      fallback,
      motivosFallback
    });
  }
}

for (let semana = 1; semana <= datosRIR.semanas_totales; semana++) {
  for (const item of seleccionBase) {
    const { slot, ejercicio, fallback, motivosFallback } = item;
    const ref = referencias.get(String(ejercicio.id_ejercicio)) || null;
    const rirMin = datosRIR.rir_semanal_min?.[semana - 1] ?? datosRIR.rir_semanal?.[semana - 1] ?? 4;
    const rirMax = datosRIR.rir_semanal_max?.[semana - 1] ?? datosRIR.rir_semanal?.[semana - 1] ?? rirMin;
    const progresion = progresionBase(ejercicio, slot, ref, semana, rirMin, rirMax);
    const tecnicaAvanzada = datosRIR.tecnicas_avanzadas_habilitadas && semana >= 3 && !['primario', 'aerobico'].includes(slot.tipo_slot) && !ejercicio.es_axial ? 'permitida' : null;

    salida.push({ json: {
      id_ejercicio: ejercicio.id_ejercicio,
      semana,
      dia_numero: slot.dia_numero,
      dia_tipo: slot.dia_tipo,
      orden_ejercicio: item.orden_ejercicio,
      orden_matriz: slot.orden,
      tipo_slot: slot.tipo_slot,
      zona: slot.zona,
      objetivo_muscular: slot.objetivo_muscular || slot.musculo_slot || null,
      patron_slot: slot.patron_slot || null,
      maquina_slot: slot.maquina_slot || null,
      tipo_slot_original: slot.tipo_slot_original || null,
      fuente_matriz: slot.fuente_matriz || plan.rutina_tipo,
      rir_objetivo: rirMax,
      rir_objetivo_min: rirMin,
      rir_objetivo_max: rirMax,
      peso_sugerido: round2(progresion.peso),
      series: progresion.series,
      reps_min: progresion.reps_min,
      reps_max: progresion.reps_max,
      tempo: progresion.tempo,
      descanso_seg: progresion.descanso,
      duracion_objetivo_min: progresion.duracion,
      estado_microciclo: progresion.estado,
      tecnica_avanzada: tecnicaAvanzada,
      fallback_aplicado: fallback,
      motivo_fallback: motivosFallback || null,
      comentario: [
        `Semana ${semana} - Dia ${slot.dia_numero} - ${slot.dia_tipo}`,
        `Matriz: ${slot.fuente_matriz || plan.rutina_tipo}`,
        `Orden matriz: ${slot.orden}`,
        `Slot: ${slot.tipo_slot}`,
        slot.patron_slot ? `Patron: ${slot.patron_slot}` : null,
        slot.maquina_slot ? `Maquina: ${slot.maquina_slot}` : null,
        slot.musculo_slot ? `Musculo: ${slot.musculo_slot}` : null,
        `RIR objetivo ${rirMin}-${rirMax}`,
        `Iteracion microciclo: ${progresion.comentario}`,
        `Base mesociclo estable; ejercicio unico dentro del microciclo; mesociclo metodo ${mesoMetodo}`,
        slot.fallback_plan ? `Fallback planificado: ${slot.fallback_plan}` : null,
        fallback ? `Fallback: ${motivosFallback}` : null,
        tecnicaAvanzada ? 'Tecnica avanzada permitida en accesorio estable' : null
      ].filter(Boolean).join(' | ')
    }});
  }
}

return salida.sort((a, b) => {
  if (a.json.semana !== b.json.semana) return a.json.semana - b.json.semana;
  if (a.json.dia_numero !== b.json.dia_numero) return a.json.dia_numero - b.json.dia_numero;
  return a.json.orden_ejercicio - b.json.orden_ejercicio;
});

