// CONTRATO WEBHOOK APPSMITH - Algoritmo de Rutina v3.6 microciclos iterativos
// Metodo: POST
// Path: /webhook/routines_automation
// Content-Type: application/json
// Acepta objeto, array, string JSON u objeto dentro de body.
//
// Payload recomendado:
// {
//   "id_alumno": 260,
//   "objetivo": "recomposicion_corporal",
//   "prioridad_recomposicion": "musculatura",
//   "enfoque_principal": "full_body",
//   "enfoque_especifico": "gluteo",
//   "debilidad": null
// }
//
// enfoque_principal permitido:
// full_body, torso, pierna, pierna_torso, torso_pierna,
// fullbody_torso_pierna, torso_pierna_torso, pierna_torso_pierna,
// pierna_torso_pierna_torso, torso_torso_pierna_torso, ff, aem, aepm.
//
// enfoque_especifico permitido:
// null, gluteo, abdomen, manguito_rotador, espalda, hombro, pectoral,
// brazos, cuadriceps, isquio, gastrocnemio.
//
// debilidad permitida: null, gluteo, abdomen, manguito_rotador.
// V2: null se transforma en abdomen; gluteo en torso/AEM se transforma en abdomen; manguito_rotador aplica en todo tipo de dia.
//
// Iteracion microciclos:
// - El workflow reutiliza el mesociclo activo si existe.
// - Los bloques se actualizan por clave (id_mesociclo, semana_meso, dia_numero, orden).
// - Un bloque con log_entrenamiento asociado no se sobreescribe.
// - RIR se guarda como rir_objetivo, rir_objetivo_min y rir_objetivo_max.
// - Aerobico guarda duracion_objetivo_min = 10.
return $input.all();

