WITH previo AS (
    SELECT DISTINCT be.id_ejercicio
    FROM adt.bloques_ejercicios be
    JOIN adt.mesociclos m ON be.id_mesociclo = m.id_mesociclo
    WHERE m.id_macrociclo = {{ $("Code in JavaScript").first().json.id_macrociclo }}
      AND m.numero_meso_en_macro = {{ Math.max(1, Number($("Insertar Mesociclo Actual").first().json.numero_meso_en_macro || $("Code in JavaScript").first().json.numero_meso || 1) - 1) }}
      AND {{ Number($("Insertar Mesociclo Actual").first().json.numero_meso_en_macro || $("Code in JavaScript").first().json.numero_meso || 1) }} > 1
)
SELECT id_ejercicio FROM previo
UNION ALL
SELECT NULL::int AS id_ejercicio WHERE NOT EXISTS (SELECT 1 FROM previo);
